<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Transkrip Akademik</title><style>body{font:12px Arial;margin:35px;color:#222}h2,h3{text-align:center;margin:4px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #555;padding:7px;text-align:left}.meta{margin-top:25px}.print{margin:15px 0}@media print{.print{display:none}}</style></head><body><button class="print" onclick="window.print()">Cetak</button><h2>TRANSKRIP AKADEMIK</h2><h3>SISTEM INFORMASI AKADEMIK</h3><div class="meta">Nama: <?= esc($nama) ?><br>NIM: <?= esc($nim) ?><br>IPK: <?= esc($ipk) ?></div><table><thead><tr><th>No</th><th>Kode</th><th>Mata Kuliah</th><th>SKS</th><th>Nilai</th><th>Periode</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><?= esc($r['kode']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['sks']) ?></td><td><?= esc($r['nilai']??'-') ?></td><td><?= esc($r['tahun_ajaran'].' '.$r['semester']) ?></td></tr><?php endforeach ?></tbody></table></body></html>